insert into public.dictation_clip_answers(clip_id,reference_text) values ('9c3c590e-5266-5ab8-aee9-dcfef0b33a71','You philosophers, however raised above your own bodies you may be, must really not forget that we poor worldlings have bones to be broken.''') on conflict (clip_id) do nothing;
