insert into public.dictation_clip_answers(clip_id,reference_text) values ('e4a965de-0cbe-511b-b738-721d2be95470','For a time had arrived, in which no teacher who did not put forth the most lofty pretensions to righteousness could expect a hearing.') on conflict (clip_id) do nothing;
