insert into public.dictation_clip_answers(clip_id,reference_text) values ('6a363546-28db-5e64-8b49-4847075071f3','"He''s disturbed in his mind,--quite ''orrid," Bozzle said when he got back to his wife.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('4fd3f98d-94c7-53c4-8b5c-5d68b4ef2741','quick','libritts:dev-clean:3536_8226_000031_000001','Clip 092 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/3f1dffb80794185c81a215d77363aa0a24c15719bc4412905ee359a4700c5d8f.wav','3f1dffb80794185c81a215d77363aa0a24c15719bc4412905ee359a4700c5d8f',125804,2620,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('4fd3f98d-94c7-53c4-8b5c-5d68b4ef2741','"He cursed and swore as made even me feel bad."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('de247775-c6c9-5f29-86b7-2810dc1aaf60','quick','libritts:dev-clean:3536_8226_000021_000011','Clip 093 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/5d14eb8e1b9a0cb27db5de42694e889c4c93f72c4c8f28644c41e5b1cc233efc.wav','5d14eb8e1b9a0cb27db5de42694e889c4c93f72c4c8f28644c41e5b1cc233efc',207404,4320,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('de247775-c6c9-5f29-86b7-2810dc1aaf60','"Perhaps you could put on your coat, and walk out with me for a few minutes," said Trevelyan.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('6b99149e-279d-5f3b-a06a-a3ca5c594255','quick','libritts:dev-clean:3536_8226_000017_000002','Clip 094 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/645626952426f1c7467c9f35de9ab1ae9f656468baba3d421eb0d4cb0a8e3d7e.wav','645626952426f1c7467c9f35de9ab1ae9f656468baba3d421eb0d4cb0a8e3d7e',123884,2580,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('6b99149e-279d-5f3b-a06a-a3ca5c594255','He''ll get the child fast enough if he''ll go before the court."') on conflict (clip_id) do nothing;
