insert into public.dictation_clip_answers(clip_id,reference_text) values ('8a83f9c5-7572-5166-bd7a-db369f72b100','mrs Bozzle, who well understood that business was business, and that wives were not business, felt no anger at this, and handed her husband his best coat.') on conflict (clip_id) do nothing;
