insert into public.dictation_clip_answers(clip_id,reference_text) values ('9a3c5449-1db3-5483-a56c-f4ead671e0d6','"Why not?" Trevelyan could perceive at once that the authority which he had once respected had gone from the man.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('b90b2fe7-82ce-5b20-8b4a-572fa0e75afe','quick','libritts:dev-clean:3536_8226_000027_000000','Clip 099 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/5a5c9ba10b0e35c753e66ab2765af98b282f91acb3f1f06198e353a4c20f759c.wav','5a5c9ba10b0e35c753e66ab2765af98b282f91acb3f1f06198e353a4c20f759c',63882,1330,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('b90b2fe7-82ce-5b20-8b4a-572fa0e75afe','"You mean the Colonel, sir.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('34c86183-32bd-58d2-93d7-73f168aca7f3','quick','libritts:dev-clean:3536_8226_000019_000000','Clip 100 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/fcee2d2cf7634b1c3598783afef2419e20e260467489f4ddb198bc82ea14c6da.wav','fcee2d2cf7634b1c3598783afef2419e20e260467489f4ddb198bc82ea14c6da',160364,3340,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('34c86183-32bd-58d2-93d7-73f168aca7f3','"It''s love for her as has done it then," said Bozzle, shaking his head.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('64dad14b-6bfa-5f46-ba59-189918c46c88','quick','libritts:dev-clean:3536_8226_000018_000002','Clip 101 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/6251efd722b13fa760de0053adcccb4048e4e1772e10603ef89831d6d8e9cdcb.wav','6251efd722b13fa760de0053adcccb4048e4e1772e10603ef89831d6d8e9cdcb',383084,7980,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('64dad14b-6bfa-5f46-ba59-189918c46c88','"I''ll tell you what it is, b," exclaimed mrs Bozzle, "it''s my belief as he ain''t quite right up here;" and mrs Bozzle touched her forehead.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('a616652e-330c-57da-8463-03f8c6b5abf3','quick','libritts:dev-clean:3536_8226_000010_000004','Clip 102 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/4279df8ce56d02ecb2b2685a9191ccfbced155317f90a2e3dd0dd2ebba1f376a.wav','4279df8ce56d02ecb2b2685a9191ccfbced155317f90a2e3dd0dd2ebba1f376a',464684,9680,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('a616652e-330c-57da-8463-03f8c6b5abf3','It ain''t the regular line of business, Bozzle; and there ain''t no good to be got, never, by going off the regular line." Whereupon Bozzle scratched his head and again read the letter.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('f00b048d-c0b2-57c4-b09e-360f678331fe','quick','libritts:dev-clean:3536_8226_000024_000003','Clip 103 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/573801c74555767a0f1217faffd20955a8c5fc00fa062bcf6b825ed8b4f41077.wav','573801c74555767a0f1217faffd20955a8c5fc00fa062bcf6b825ed8b4f41077',234280,4880,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('f00b048d-c0b2-57c4-b09e-360f678331fe','But he had been found with his coat off, and a baby in his arms, and he could not recover himself.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('5a339f36-9758-5597-a6e9-a0b6d58b6055','quick','libritts:dev-clean:3536_8226_000026_000006','Clip 104 · voice 3536','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 3536 · CC BY 4.0','dictation/clips/quick/b6506496a89f97fb9e78ca18acb86f43f0d0a39a70b688ff66325c337a0b83d2.wav','b6506496a89f97fb9e78ca18acb86f43f0d0a39a70b688ff66325c337a0b83d2',441164,9190,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('5a339f36-9758-5597-a6e9-a0b6d58b6055','As he went about, his eyes were ever cast downwards, and he walked with a quick shuffling gait, and he suspected others, feeling that he himself was suspected.') on conflict (clip_id) do nothing;
