insert into public.dictation_clip_answers(clip_id,reference_text) values ('28200371-c1a7-552d-ad7f-97c630463a2d','Then came all those years without you, lonely and hurt and discouraged; those decent young fellows and poor Mac, and me never heeding-hard as a steel spring.') on conflict (clip_id) do nothing;
