insert into public.dictation_clip_answers(clip_id,reference_text) values ('dc5f0cca-04c0-56dd-885f-f0e395069b46','"Just something Bartley.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('512cfe17-3f78-5fb0-ac7a-851435c66edc','quick','libritts:dev-clean:1462_170142_000038_000006','Clip 192 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/a088e3245142605da56d9b4fdc716ce61a0df1c24f1bae435bd5f82c5ecee95b.wav','a088e3245142605da56d9b4fdc716ce61a0df1c24f1bae435bd5f82c5ecee95b',287564,5990,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('512cfe17-3f78-5fb0-ac7a-851435c66edc','"You want to tell me that you can only see me like this, as old friends do, or out in the world among people?') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('1c245a7d-aa91-5002-a151-eadd8dffd707','quick','libritts:dev-clean:1462_170142_000040_000004','Clip 193 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/3d5b357a1d1ae396179229f93a34ee42c504b910937790eaff8ec66e926b5987.wav','3d5b357a1d1ae396179229f93a34ee42c504b910937790eaff8ec66e926b5987',320204,6670,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('1c245a7d-aa91-5002-a151-eadd8dffd707','What I mean is that I want you to promise never to see me again, no matter how often I come, no matter how hard I beg."') on conflict (clip_id) do nothing;
