insert into public.dictation_clip_answers(clip_id,reference_text) values ('675117e8-cbcd-5cb2-9d25-f2a5eee5bc0f','I will ask the least imaginable, but I must have SOMETHING!"') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('dd8a3596-f7d4-54a9-a039-aadde61960a6','quick','libritts:dev-clean:1462_170142_000002_000005','Clip 195 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/fd79c6eb48483d9353311e41788953bfa9eaf3cc525062e53080f7c4a9251ff1.wav','fd79c6eb48483d9353311e41788953bfa9eaf3cc525062e53080f7c4a9251ff1',87404,1820,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
