insert into public.dictation_clip_answers(clip_id,reference_text) values ('35123b0b-1c79-5949-816e-16caa17acfd5','"When did you first begin to feel like this, Bartley?"') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('f314de9a-a574-51cd-83f7-27ee176cb83b','quick','libritts:dev-clean:1462_170142_000002_000000','Clip 198 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/060664c15e4057141fe99f210430ca494ffb1ce6b78c1347163c24eb748fd4d8.wav','060664c15e4057141fe99f210430ca494ffb1ce6b78c1347163c24eb748fd4d8',420524,8760,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('f314de9a-a574-51cd-83f7-27ee176cb83b','Emerging at Euston at half past three o''clock in the afternoon, Alexander had his luggage sent to the Savoy and drove at once to Bedford Square.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('2880f4f3-4b74-5c4e-a514-e800f5a019e4','quick','libritts:dev-clean:1462_170142_000009_000000','Clip 199 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/b518b9727e564eafdd4de485f4e78e657105738031ae4aec26404aa9cc971afe.wav','b518b9727e564eafdd4de485f4e78e657105738031ae4aec26404aa9cc971afe',100364,2090,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('2880f4f3-4b74-5c4e-a514-e800f5a019e4','Hilda took a quick, soft breath.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('a7ab85cc-793d-575a-9e7b-2f1b3bfa586e','quick','libritts:dev-clean:1462_170142_000040_000002','Clip 200 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/5f6868742f042d9a4f448fe6181e1a9d8215f433fc1050dc3ae6d0cc3b6db135.wav','5f6868742f042d9a4f448fe6181e1a9d8215f433fc1050dc3ae6d0cc3b6db135',102284,2130,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('a7ab85cc-793d-575a-9e7b-2f1b3bfa586e','"It''s got to be a clean break, Hilda.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('b5decf83-64a6-5055-b531-d6ad9cda89a7','quick','libritts:dev-clean:1462_170142_000048_000002','Clip 201 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/62458f9aba6a761d0555ea53547e2da7bbd4d2922039cebb375f11358d3b5f04.wav','62458f9aba6a761d0555ea53547e2da7bbd4d2922039cebb375f11358d3b5f04',98924,2060,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('b5decf83-64a6-5055-b531-d6ad9cda89a7','Forget everything except that I am here."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('9071f205-56c5-51a1-85dc-f748a09146a4','quick','libritts:dev-clean:1462_170142_000033_000002','Clip 202 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/f7743eb643729d4261a03db81e79dab1fcc2210a4379c8d29384896d92eeb514.wav','f7743eb643729d4261a03db81e79dab1fcc2210a4379c8d29384896d92eeb514',178604,3720,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('9071f205-56c5-51a1-85dc-f748a09146a4','At least, tell me that you believe I thought I was making you happy."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('875b3cbf-ccb4-592d-9091-e8b097b7bf55','quick','libritts:dev-clean:1462_170142_000038_000007','Clip 203 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/701705a544983c50f29720edaf334f1dd6ada0213917e0d6c7cab8e78fa5a897.wav','701705a544983c50f29720edaf334f1dd6ada0213917e0d6c7cab8e78fa5a897',49484,1030,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('875b3cbf-ccb4-592d-9091-e8b097b7bf55','I can do that."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('3488f175-5f7b-59d4-910c-b8c3fecad8d9','quick','libritts:dev-clean:1462_170142_000021_000001','Clip 204 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/563135925cf515d8c09d1b6c62705295c9994496ef701e82322b737d7b7194a2.wav','563135925cf515d8c09d1b6c62705295c9994496ef701e82322b737d7b7194a2',193964,4040,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('3488f175-5f7b-59d4-910c-b8c3fecad8d9','"I am not a man who can live two lives," he went on feverishly.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('9059b935-9d62-562b-8f68-d3b113f218c8','quick','libritts:dev-clean:1462_170142_000002_000001','Clip 205 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/5de172516eff88018eaa114fe146754261534968141ee076849447ea2941548b.wav','5de172516eff88018eaa114fe146754261534968141ee076849447ea2941548b',336524,7010,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('9059b935-9d62-562b-8f68-d3b113f218c8','When Marie met him at the door, even her strong sense of the proprieties could not restrain her surprise and delight.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('ac65ce03-e812-5dec-bc19-4fed841d7d06','quick','libritts:dev-clean:1462_170142_000043_000006','Clip 206 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/7f783fd44b91cef760854cbeffc51a5c65f27033e7c56d097150ac5f5462be75.wav','7f783fd44b91cef760854cbeffc51a5c65f27033e7c56d097150ac5f5462be75',159886,3330,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('ac65ce03-e812-5dec-bc19-4fed841d7d06','I''m growing older, and you''ve got my young self here with you.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('4486a81f-7829-5bc5-862b-71aa4dbb90a3','quick','libritts:dev-clean:1462_170142_000008_000001','Clip 207 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/0d5347ad20462bd405648b549c43ff7dc8efc2914a790fee80238a13c17dc605.wav','0d5347ad20462bd405648b549c43ff7dc8efc2914a790fee80238a13c17dc605',101324,2110,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('4486a81f-7829-5bc5-862b-71aa4dbb90a3','"It''s the whole thing that troubles me, Hilda.') on conflict (clip_id) do nothing;
