insert into public.dictation_clip_answers(clip_id,reference_text) values ('4a4731e7-3fab-5cbb-bcca-a34418dcff56','"I didn''t know it before, Hilda, on my honor I didn''t, but I believe it was because, deep down in me somewhere, I was hoping I might drive you to do just this.') on conflict (clip_id) do nothing;
