insert into public.dictation_clip_answers(clip_id,reference_text) values ('6934878d-e3a7-5293-b563-39f664e07eb4','There was something about him that made Hilda wish herself at her hotel again, in the street below, anywhere but where she was.') on conflict (clip_id) do nothing;
