insert into public.dictation_clip_answers(clip_id,reference_text) values ('4f36f0c4-2412-5aae-9718-5683fb93e37f','"Is this the way you mean to answer it, Hilda?" he asked unsteadily.') on conflict (clip_id) do nothing;
