insert into public.dictation_clip_answers(clip_id,reference_text) values ('6a99eaa5-d2dc-53a8-9b63-73675f3d5d2d','I saw that interview in the paper yesterday, telling where you were, and I thought I had to see you.') on conflict (clip_id) do nothing;
