insert into public.dictation_clip_answers(clip_id,reference_text) values ('6cf20802-ee9d-566c-a563-20e6a4cb1ea7','The yellow light from the student''s lamp fell on his hands and the purple sleeves of his velvet smoking jacket, but his flushed face and big, hard head were in the shadow.') on conflict (clip_id) do nothing;
