insert into public.dictation_clip_answers(clip_id,reference_text) values ('343d4291-7e0e-5b87-b9e5-7a2f677f3210','I told myself that if I were really thinking of you, and not of myself, a letter would be better than nothing.') on conflict (clip_id) do nothing;
