insert into public.dictation_clip_answers(clip_id,reference_text) values ('5229bbf0-7aaa-511d-bd23-af37a4406a23','It was furnished with the cast off possessions of his bachelor days and with odd things which he sheltered for friends of his who followed itinerant and more or less artistic callings.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('53ea28cd-8eeb-5c56-ac72-e6b4b3383626','quick','libritts:dev-clean:1462_170145_000003_000001','Clip 299 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/30ed5f2b423e00b459bb724599dbd600e474cb1b0a9db0c801ff1c57ff4a5cf4.wav','30ed5f2b423e00b459bb724599dbd600e474cb1b0a9db0c801ff1c57ff4a5cf4',395564,8240,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('53ea28cd-8eeb-5c56-ac72-e6b4b3383626','His business often called him to New York, and he had kept an apartment there for years, subletting it when he went abroad for any length of time.') on conflict (clip_id) do nothing;
