insert into public.dictation_clip_answers(clip_id,reference_text) values ('6d70f569-6d3c-597e-a6c8-25f343010b8a','I don''t know what I ought to say, but I don''t believe you''d be happy; truly I don''t.') on conflict (clip_id) do nothing;
