insert into public.dictation_clip_answers(clip_id,reference_text) values ('7271c608-dd2c-5ea8-a32e-93d8af05c267','I''ve been up in Canada with my bridge, and I arranged not to come to New York until after you had gone.') on conflict (clip_id) do nothing;
