insert into public.dictation_clip_answers(clip_id,reference_text) values ('2d1ffd1a-1bea-51b1-b26b-1a587fb74b82','"Try him again, Hilda.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('45592e57-4b99-54e5-b82f-ec3e91b10464','quick','libritts:dev-clean:1462_170145_000029_000002','Clip 312 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/11aa387fbf8da0e37997c882b53417c735e8f43daaecd0bd60ce8e598e3d09fb.wav','11aa387fbf8da0e37997c882b53417c735e8f43daaecd0bd60ce8e598e3d09fb',228524,4760,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('45592e57-4b99-54e5-b82f-ec3e91b10464','But afterward I shan''t have an opportunity to explain, for I shan''t be seeing you again."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('8215d473-06ff-5051-9909-ee8c8c5d9b86','quick','libritts:dev-clean:1462_170145_000014_000004','Clip 313 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/f9127c74da4ecf34314f48a2c40ab22aad7c641fb5d984f806ba8cc9b9ea8b29.wav','f9127c74da4ecf34314f48a2c40ab22aad7c641fb5d984f806ba8cc9b9ea8b29',215564,4490,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('8215d473-06ff-5051-9909-ee8c8c5d9b86','I think I have felt that you were coming." He bent his face over her hair.') on conflict (clip_id) do nothing;
