insert into public.dictation_clip_answers(clip_id,reference_text) values ('c0ac933f-48b4-5867-ab4f-bca1a10cc1a4','"I came to tell you that I''m willing to do as you asked me.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('2c301a52-fac5-5bef-b4d5-10e5ac27ef5f','quick','libritts:dev-clean:1462_170145_000017_000003','Clip 316 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/7175e7d179dc8f179c8f15a4a97e92111cf7d10aa1844bb6dda37b2ce15653b2.wav','7175e7d179dc8f179c8f15a4a97e92111cf7d10aa1844bb6dda37b2ce15653b2',72524,1510,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('2c301a52-fac5-5bef-b4d5-10e5ac27ef5f','"What am I to do, Hilda?"') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('de907450-bf90-5332-bd48-d18fec849f7e','quick','libritts:dev-clean:1462_170145_000009_000002','Clip 317 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/e2efdf5554122f6c234853ce8d9d641e3c9c69965630be2c3870cbd184f885d9.wav','e2efdf5554122f6c234853ce8d9d641e3c9c69965630be2c3870cbd184f885d9',126284,2630,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('de907450-bf90-5332-bd48-d18fec849f7e','Can''t you see, Bartley, that I''m terribly frightened?') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('21a0ca1b-4dbd-59fe-8e4f-87296493c0f0','quick','libritts:dev-clean:1462_170145_000028_000002','Clip 318 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/72e2dc949530e582bab03873f88dde5cf9783390207186cb2c2cc5b1e2c49670.wav','72e2dc949530e582bab03873f88dde5cf9783390207186cb2c2cc5b1e2c49670',68684,1430,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('21a0ca1b-4dbd-59fe-8e4f-87296493c0f0','Aren''t you trying to frighten me?"') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('525b4776-2c44-5f48-8d08-22e834696f6a','quick','libritts:dev-clean:1462_170145_000008_000002','Clip 319 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/5cad41501fdd2130f688cff7d3b551f450ef8ba6f0077327a76f18c356411537.wav','5cad41501fdd2130f688cff7d3b551f450ef8ba6f0077327a76f18c356411537',447404,9320,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('525b4776-2c44-5f48-8d08-22e834696f6a','Let me take off your coat-and your boots; they''re oozing water." He knelt down and began to unlace her shoes, while Hilda shrank into the chair.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('c8a16757-1775-5d0f-b6d7-9b20408c2215','quick','libritts:dev-clean:1462_170145_000012_000001','Clip 320 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/263cbd19b5af3521b389d274e9431647f531cd8d9024edd825d6215e3de94396.wav','263cbd19b5af3521b389d274e9431647f531cd8d9024edd825d6215e3de94396',130604,2720,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('c8a16757-1775-5d0f-b6d7-9b20408c2215','"Did you think I had forgotten you were in town, Hilda?') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('b6510908-fc44-593b-84a3-2d055ec2b8ce','quick','libritts:dev-clean:1462_170145_000020_000000','Clip 321 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/2222427206eb0640008271ba3bb38fbd36e81c87c685e0221de2947c3be6f067.wav','2222427206eb0640008271ba3bb38fbd36e81c87c685e0221de2947c3be6f067',72524,1510,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('b6510908-fc44-593b-84a3-2d055ec2b8ce','"Oh, it doesn''t matter much!') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('f3867bd9-6b58-5c2a-acae-1fbfc0a870f2','quick','libritts:dev-clean:1462_170145_000027_000003','Clip 322 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/9b22f462c287fd1bb832380127d7d8db99c6a0a78742017760a73b6e31a220e7.wav','9b22f462c287fd1bb832380127d7d8db99c6a0a78742017760a73b6e31a220e7',140684,2930,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('f3867bd9-6b58-5c2a-acae-1fbfc0a870f2','When he looked over his shoulder she was lacing her boots.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('bdf89de3-9be3-57bb-ad86-4f6b3473b561','quick','libritts:dev-clean:1462_170145_000031_000001','Clip 323 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/6052e82282341e9bafb7423a78458b25a85087daef67fc44749ed4526640adde.wav','6052e82282341e9bafb7423a78458b25a85087daef67fc44749ed4526640adde',280364,5840,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('bdf89de3-9be3-57bb-ad86-4f6b3473b561','Don''t do anything like that rashly." His face grew troubled. "You wouldn''t be happy.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('5019bc19-b5a8-57d2-89fe-ca14e8045402','quick','libritts:dev-clean:1462_170138_000015_000011','Clip 324 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/53c6e33726bb88cd087a24b7d84f4c70ef2ebefa538624140c81305c76ea9d83.wav','53c6e33726bb88cd087a24b7d84f4c70ef2ebefa538624140c81305c76ea9d83',169964,3540,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('5019bc19-b5a8-57d2-89fe-ca14e8045402','Sir Harry Towne, mr Bartley Alexander, the American engineer."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('7ca02f1f-2a72-5b04-8d99-b189faee4906','quick','libritts:dev-clean:1462_170138_000023_000011','Clip 325 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/a63adc921acd8c32e4d412c566d3b7ba1348168b2e1978ef53582b22a4ce5b85.wav','a63adc921acd8c32e4d412c566d3b7ba1348168b2e1978ef53582b22a4ce5b85',246764,5140,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('7ca02f1f-2a72-5b04-8d99-b189faee4906','I shouldn''t wonder- But they''ve probably spoiled her, so that she''d be tiresome if one met her again."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('e05faaf0-82bd-535b-b010-e9f15983c859','quick','libritts:dev-clean:1462_170138_000016_000000','Clip 326 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/9d978e0d4ad106d5d9c2c6f2bd9cf62491658f390767c00b9a151034d55673e3.wav','9d978e0d4ad106d5d9c2c6f2bd9cf62491658f390767c00b9a151034d55673e3',254444,5300,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('e05faaf0-82bd-535b-b010-e9f15983c859','Sir Harry Towne bowed and said that he had met mr Alexander and his wife in Tokyo.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('bb53a3d1-87ad-55f1-8b56-7a9e8f3cbdf0','quick','libritts:dev-clean:1462_170138_000024_000000','Clip 327 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/7f2c3d8f37fa947b1364da01cfb05adc7eaf8ddd0dbd1dfd4a7f34c976c6c9cd.wav','7f2c3d8f37fa947b1364da01cfb05adc7eaf8ddd0dbd1dfd4a7f34c976c6c9cd',108526,2260,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('bb53a3d1-87ad-55f1-8b56-7a9e8f3cbdf0','Bartley smiled and yawned and went to bed.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('90cdfa92-9868-529b-8b79-f113b54f577b','quick','libritts:dev-clean:1462_170138_000003_000001','Clip 328 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/b9561e7737a18e370f20eebff1cb6895b4cade72a40a9a8d0d5c6995c4af2829.wav','b9561e7737a18e370f20eebff1cb6895b4cade72a40a9a8d0d5c6995c4af2829',99404,2070,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('90cdfa92-9868-529b-8b79-f113b54f577b','"It''s tremendously well put on, too.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('c4a99d08-b8d0-5192-b6b8-17684538f1e4','quick','libritts:dev-clean:1462_170138_000022_000013','Clip 329 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/8d4143012b963777a3e5e76eee341c98ee0fe7065ba87aa29e00e8bd98bf162a.wav','8d4143012b963777a3e5e76eee341c98ee0fe7065ba87aa29e00e8bd98bf162a',188688,3930,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('c4a99d08-b8d0-5192-b6b8-17684538f1e4','"All the same," he lifted his glass, "here''s to you, little Hilda.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('6bb8d6cd-633f-59e5-96f3-273b0e9a56c7','quick','libritts:dev-clean:1462_170138_000018_000000','Clip 330 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/f756dd4ebd7d18278f280ac2451f152c20778f6af140d869d8d7a92ec51ef316.wav','f756dd4ebd7d18278f280ac2451f152c20778f6af140d869d8d7a92ec51ef316',179568,3740,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('6bb8d6cd-633f-59e5-96f3-273b0e9a56c7','"I say, Sir Harry, the little girl''s going famously to night, isn''t she?"') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('652ea1a9-5924-5c6e-beeb-0b4e0b821133','quick','libritts:dev-clean:1462_170138_000015_000003','Clip 331 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/6cfbf8fd800ae024f04ccbe0a02f4f0248d31b5d716d18acabe15273fd95c2af.wav','6cfbf8fd800ae024f04ccbe0a02f4f0248d31b5d716d18acabe15273fd95c2af',84044,1750,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('652ea1a9-5924-5c6e-beeb-0b4e0b821133','She doesn''t take up with anybody, you know.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('8f0ce0d2-e7bf-52ee-9025-3245666b05f2','quick','libritts:dev-clean:1462_170138_000021_000003','Clip 332 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/d97da87b9030c4419f9af96e2d18e7df3b43c7f76a7f55441d58cdbb02b5e104.wav','d97da87b9030c4419f9af96e2d18e7df3b43c7f76a7f55441d58cdbb02b5e104',424844,8850,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('8f0ce0d2-e7bf-52ee-9025-3245666b05f2','In the half light he looked about at the stalls and boxes and smiled a little consciously, recalling with amusement Sir Harry''s judicial frown.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('57e9cc18-6f98-57e2-9bfa-84e014a2db6e','quick','libritts:dev-clean:1462_170138_000001_000004','Clip 333 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/7a1b77bf43d0908e6e5816c356b2d7a45a6f1fe7cf80299ec4d3936d7fa135e1.wav','7a1b77bf43d0908e6e5816c356b2d7a45a6f1fe7cf80299ec4d3936d7fa135e1',465644,9700,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('57e9cc18-6f98-57e2-9bfa-84e014a2db6e','He spoke with an extreme Oxford accent, and when he was talking well, his face sometimes wore the rapt expression of a very emotional man listening to music.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('a6e7a68d-f412-5e6f-b6e1-d984dc56f5b1','quick','libritts:dev-clean:1462_170138_000023_000010','Clip 334 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/6ec7cfd0771963282f9e48e1901d4e4f07355d55978171b49f890539e107b93f.wav','6ec7cfd0771963282f9e48e1901d4e4f07355d55978171b49f890539e107b93f',119086,2480,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('a6e7a68d-f412-5e6f-b6e1-d984dc56f5b1','I shouldn''t wonder if she could laugh about it with me now.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('e86a41b2-f190-5aa1-85c4-97985a184f7f','quick','libritts:dev-clean:1462_170138_000015_000007','Clip 335 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/567c62caf5666e8f5f4f776e1ec7b34a6966ba5f2d5fb4017afabcecf8abd6a5.wav','567c62caf5666e8f5f4f776e1ec7b34a6966ba5f2d5fb4017afabcecf8abd6a5',446924,9310,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('e86a41b2-f190-5aa1-85c4-97985a184f7f','Blinking up at the lights, Mainhall added in his luxurious, worldly way: "She''s an elegant little person, and quite capable of an extravagant bit of sentiment like that.') on conflict (clip_id) do nothing;
