insert into public.dictation_clip_answers(clip_id,reference_text) values ('76b284d6-1418-5719-9249-e7f9a3a70ebf','She doubtless hasn''t thought of me for years." He felt the enthusiasm of the house at once, and in a few moments he was caught up by the current of MacConnell''s irresistible comedy.') on conflict (clip_id) do nothing;
