insert into public.dictation_clip_answers(clip_id,reference_text) values ('df89f549-f237-5aba-96d7-1956dd65f54b','Just then they drove up to the Duke of York''s, so Alexander did not commit himself, but followed Mainhall into the theatre.') on conflict (clip_id) do nothing;
