insert into public.dictation_clip_answers(clip_id,reference_text) values ('f53a03c7-3cdd-5867-8b5d-ef4d399287c6','Do you know, Alexander,"--Mainhall looked with perplexity up into the top of the hansom and rubbed his pink cheek with his gloved finger,--"do you know, I sometimes think of taking to criticism seriously myself.') on conflict (clip_id) do nothing;
