insert into public.dictation_clip_answers(clip_id,reference_text) values ('5b316332-755a-57cd-b651-3aad8f5a0579','When she began to dance, by way of showing the gossoons what she had seen in the fairy rings at night, the house broke into a prolonged uproar.') on conflict (clip_id) do nothing;
