insert into public.dictation_clip_answers(clip_id,reference_text) values ('08bf1c51-d7a4-540d-94ea-4aecefebd580','He had not thought of Hilda Burgoyne for years; indeed, he had almost forgotten her.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('520729bd-bb81-5347-b5c2-4e7a7baeffa8','quick','libritts:dev-clean:1462_170138_000012_000002','Clip 359 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/de7f2cf45251d2c241d754d14059d5529eb330942e857c17ec9c579c832f9615.wav','de7f2cf45251d2c241d754d14059d5529eb330942e857c17ec9c579c832f9615',147884,3080,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('520729bd-bb81-5347-b5c2-4e7a7baeffa8','Dear me, Mac, the girl couldn''t possibly be better, you know."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('3c8b6f16-064e-5d2b-8dc3-908d2dfe5b0f','quick','libritts:dev-clean:1462_170138_000023_000002','Clip 360 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/c8052cf9838ce257cf2f01fe80d0bbad1c70ec75b80814a755ba3dc4ede6dbb2.wav','c8052cf9838ce257cf2f01fe80d0bbad1c70ec75b80814a755ba3dc4ede6dbb2',161324,3360,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('3c8b6f16-064e-5d2b-8dc3-908d2dfe5b0f','She hadn''t much ambition then, and she was too fond of trifles.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('f747c9ff-ca14-528f-8c9b-4550e2248ff7','quick','libritts:dev-clean:1462_170138_000004_000001','Clip 361 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/be4e423634f0e5bda370a458266935bbe763120df6630293713036a6414524d7.wav','be4e423634f0e5bda370a458266935bbe763120df6630293713036a6414524d7',124364,2590,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('f747c9ff-ca14-528f-8c9b-4550e2248ff7','"Why, I haven''t heard of her for-years."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('191c3fb2-d671-5aba-b659-5532208cf0b7','quick','libritts:dev-clean:1462_170138_000009_000001','Clip 362 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/b6f7c0ce815784c5801e53f3cc02bef911250e366ce2cd634396ab6ee3f90bc0.wav','b6f7c0ce815784c5801e53f3cc02bef911250e366ce2cd634396ab6ee3f90bc0',460364,9590,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('191c3fb2-d671-5aba-b659-5532208cf0b7','They met a good many acquaintances; Mainhall, indeed, knew almost every one, and he babbled on incontinently, screwing his small head about over his high collar.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('52effd72-57e4-5083-bbba-13a7784bbd80','quick','libritts:dev-clean:1462_170138_000021_000000','Clip 363 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/4fc98cfd6633b8dec01605a1ff14b655fcebc8f6f454ce217019622a14a7a741.wav','4fc98cfd6633b8dec01605a1ff14b655fcebc8f6f454ce217019622a14a7a741',562126,11710,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('52effd72-57e4-5083-bbba-13a7784bbd80','When they reached their box the house was darkened and the orchestra was playing "The Cloak of Old Gaul." In a moment Peggy was on the stage again, and Alexander applauded vigorously with the rest.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('531765e6-a65d-5168-80c5-e08c110fb08f','quick','libritts:dev-clean:1462_170138_000005_000001','Clip 364 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/4985b220803c11c146308a9819cbc796e54138490709464c7257e1890dde9ed0.wav','4985b220803c11c146308a9819cbc796e54138490709464c7257e1890dde9ed0',128204,2670,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('531765e6-a65d-5168-80c5-e08c110fb08f','"Then you can''t have heard much at all, my dear Alexander.') on conflict (clip_id) do nothing;
