insert into public.dictation_clip_answers(clip_id,reference_text) values ('5398d4bb-7c52-5030-9fed-08ececcbecf9','I should torture myself-I couldn''t help it." After that it was easy to forget, actually to forget.') on conflict (clip_id) do nothing;
