insert into public.dictation_clip_answers(clip_id,reference_text) values ('ee7d56aa-3b6a-5049-8a1b-72d7007a6dcc','As they sat down, a burst of applause drew Alexander''s attention to the stage.') on conflict (clip_id) do nothing;
