insert into public.dictation_clip_answers(clip_id,reference_text) values ('6564d9dc-f04d-5eec-8577-4df7dd852a3c','He felt guilty and unhappy about her for a time, but after Winifred promised to marry him he really forgot Hilda altogether.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('e1a2b073-1757-568e-bd57-6bc1ac2ecf8a','quick','libritts:dev-clean:1462_170138_000001_000006','Clip 372 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/c95240cc52f6d3dee5ce519243f8f78210dfc48245e4c82049b9fd93ae473cfd.wav','c95240cc52f6d3dee5ce519243f8f78210dfc48245e4c82049b9fd93ae473cfd',328844,6850,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('e1a2b073-1757-568e-bd57-6bc1ac2ecf8a','He had preconceived ideas about everything, and his idea about Americans was that they should be engineers or mechanics.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('a48dcbbb-d309-5dcd-a55b-da537d5402b5','quick','libritts:dev-clean:1462_170138_000021_000002','Clip 373 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/d36470a67d1b50752bee6d70e33ee65f7df2264aeb80c444191e76aeae9ba87f.wav','d36470a67d1b50752bee6d70e33ee65f7df2264aeb80c444191e76aeae9ba87f',198764,4140,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('a48dcbbb-d309-5dcd-a55b-da537d5402b5','For some reason he felt pleased and flattered by the enthusiasm of the audience.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('32e271f0-e95d-5aef-aae7-114a69859ca9','quick','libritts:dev-clean:1462_170138_000023_000008','Clip 374 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/39cccbc8cd7d0a6410a88c5d63537404e9d6ad18ee64998dedb8a13816c6dbad.wav','39cccbc8cd7d0a6410a88c5d63537404e9d6ad18ee64998dedb8a13816c6dbad',89322,1860,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('32e271f0-e95d-5aef-aae7-114a69859ca9','After all, we were awfully young.') on conflict (clip_id) do nothing;
