insert into public.dictation_clip_answers(clip_id,reference_text) values ('cffc2625-69d4-575e-bc6b-c3f9d8e9c00e','Mainhall liked Alexander because he was an engineer.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('6fd8381b-0b1f-541e-86be-5550f9091bb4','quick','libritts:dev-clean:1462_170138_000012_000001','Clip 376 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/180e801c3ecb59ddbde4cf32def9c2623e9663aa00ca6e08952bc958fd77e006.wav','180e801c3ecb59ddbde4cf32def9c2623e9663aa00ca6e08952bc958fd77e006',112844,2350,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('6fd8381b-0b1f-541e-86be-5550f9091bb4','"And you''ll never bring Hilda out like this again.') on conflict (clip_id) do nothing;
