insert into public.dictation_clip_answers(clip_id,reference_text) values ('a57af278-2116-5b5c-8f09-770636520a42','She''s really MacConnell''s poetic motif, you see; makes the whole thing a fairy tale."') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('cc4a1196-0717-59de-8fb7-7bc62e8afb21','quick','libritts:dev-clean:1462_170138_000019_000002','Clip 378 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/b428a0d594731b5b96322e661016476aa7b10d88172b4cc54b5fd9bddb09d376.wav','b428a0d594731b5b96322e661016476aa7b10d88172b4cc54b5fd9bddb09d376',135400,2820,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('cc4a1196-0717-59de-8fb7-7bc62e8afb21','The fact is, she''s feeling rather seedy, poor child.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('29c6f560-d3d3-500b-95fd-0d60b876606d','quick','libritts:dev-clean:1462_170138_000004_000000','Clip 379 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/27694d962c0865eee0e1c97c923f7cee57779cecf866edfd552a4fd5646864af.wav','27694d962c0865eee0e1c97c923f7cee57779cecf866edfd552a4fd5646864af',179564,3740,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('29c6f560-d3d3-500b-95fd-0d60b876606d','"Hilda Burgoyne!" Alexander exclaimed mildly.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('86df736c-85fd-5b67-b238-3dbeba7d822b','quick','libritts:dev-clean:1462_170138_000015_000005','Clip 380 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/1c3db45cd64a87280f3ef58019fa11a5517633883542a6b2c91430b9d00877ce.wav','1c3db45cd64a87280f3ef58019fa11a5517633883542a6b2c91430b9d00877ce',256844,5350,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('86df736c-85fd-5b67-b238-3dbeba7d822b','One of your countrymen, Alexander, by the way; an American student whom she met in Paris, I believe.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('8a916cd3-4f61-5f34-b1f3-707e71a5ed8d','quick','libritts:dev-clean:1462_170138_000005_000003','Clip 381 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/d6e4d21a21a8218518b41d8e368694ffb31870decd91d1b646133c3625512734.wav','d6e4d21a21a8218518b41d8e368694ffb31870decd91d1b646133c3625512734',100844,2100,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('8a916cd3-4f61-5f34-b1f3-707e71a5ed8d','Myself, I always knew she had it in her.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('adf0e0d8-1aa3-51ed-952d-64e8b08d7675','quick','libritts:dev-clean:1462_170138_000001_000001','Clip 382 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/34a4ed1d0bdd9a8478097384c0cf4372f6a315fad829d79c030803e93df93176.wav','34a4ed1d0bdd9a8478097384c0cf4372f6a315fad829d79c030803e93df93176',534764,11140,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('adf0e0d8-1aa3-51ed-952d-64e8b08d7675','The nephew of one of the standard Victorian novelists, Mainhall bobbed about among the various literary cliques of London and its outlying suburbs, careful to lose touch with none of them.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('d9b6697d-41d5-5d8f-b6f9-ea9b5fa4ec7c','quick','libritts:dev-clean:1462_170138_000010_000000','Clip 383 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/2680ff8d40fbd014d696766172e961822bf7c1ba793c63fc8f2d4ef2ebc34374.wav','2680ff8d40fbd014d696766172e961822bf7c1ba793c63fc8f2d4ef2ebc34374',153644,3200,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('d9b6697d-41d5-5d8f-b6f9-ea9b5fa4ec7c','"MacConnell, let me introduce mr Bartley Alexander.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('4d5c529a-c844-5da6-9386-86fb2d34d808','quick','libritts:dev-clean:1462_170138_000022_000012','Clip 384 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/4f4f42e7b4aedf3052a60f851f81fa121ecefcebb09c1149b87a42633ab25747.wav','4f4f42e7b4aedf3052a60f851f81fa121ecefcebb09c1149b87a42633ab25747',196362,4090,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('4d5c529a-c844-5da6-9386-86fb2d34d808','He had been in London more or less, but he had never happened to hear of her.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('d475fd82-1f0b-57c3-85fa-44530d4cab8b','quick','libritts:dev-clean:1462_170138_000010_000002','Clip 385 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/920f1cdfde8b326d20af59cd2d66c989913e3f09a7dc3507676c02b3ff31aa55.wav','920f1cdfde8b326d20af59cd2d66c989913e3f09a7dc3507676c02b3ff31aa55',87404,1820,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('d475fd82-1f0b-57c3-85fa-44530d4cab8b','It''s going famously to night, Mac.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('a2fbe16a-29a2-5fd4-8e72-0c724887f4c8','quick','libritts:dev-clean:1462_170138_000015_000001','Clip 386 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/dc657dc45dac8dc159677423d2160d96ad6832dbe2e08606ea57dc8674bf4f8c.wav','dc657dc45dac8dc159677423d2160d96ad6832dbe2e08606ea57dc8674bf4f8c',65324,1360,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('a2fbe16a-29a2-5fd4-8e72-0c724887f4c8','"He''s hit terribly hard.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('899b1c65-5801-5131-b2b1-b2b5624c01e5','quick','libritts:dev-clean:1462_170138_000011_000001','Clip 387 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/c2933a2deb4e5c5551fc8766218148bb9b702cf9b7f8fce193aa10fc02777a23.wav','c2933a2deb4e5c5551fc8766218148bb9b702cf9b7f8fce193aa10fc02777a23',166124,3460,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('899b1c65-5801-5131-b2b1-b2b5624c01e5','"And have I done anything so fool as that, now?" he asked.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('c5c92f43-b8f2-548b-a53c-8e4f1398bba2','quick','libritts:dev-clean:1462_170138_000007_000004','Clip 388 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/e9bf679fc91e0589b886632213f0f3019192d5325b6a82549ff3e4eb4923c705.wav','e9bf679fc91e0589b886632213f0f3019192d5325b6a82549ff3e4eb4923c705',70124,1460,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('c5c92f43-b8f2-548b-a53c-8e4f1398bba2','She saves her hand, too.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('48f7f390-639a-5d13-a99d-659d99124a50','quick','libritts:dev-clean:1462_170138_000012_000000','Clip 389 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/1e98905633ba72274407f8c82aabc7505d0fb390199934f0ed779f967c250559.wav','1e98905633ba72274407f8c82aabc7505d0fb390199934f0ed779f967c250559',342764,7140,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('48f7f390-639a-5d13-a99d-659d99124a50','"That''s what I was saying," Mainhall lounged a little nearer and dropped into a tone even more conspicuously confidential.') on conflict (clip_id) do nothing;
