insert into public.dictation_clip_answers(clip_id,reference_text) values ('47ddaf3d-aa06-554d-8703-67daf5705bed','That laugh, now, when she doubles over at the hips-who ever heard it out of Galway?') on conflict (clip_id) do nothing;
