insert into public.dictation_clip_answers(clip_id,reference_text) values ('fb3df1fc-6c95-51f7-b307-a86c452b5a11','Mainhall cut in impatiently.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('42ac76e6-28a9-57ee-84c3-cb4cb615ea6c','quick','libritts:dev-clean:1462_170138_000007_000000','Clip 394 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/cdcb899eb425eaeeba3cfa58c893d016a7c1fa0f45f8e155e619ad573552094d.wav','cdcb899eb425eaeeba3cfa58c893d016a7c1fa0f45f8e155e619ad573552094d',459884,9580,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('42ac76e6-28a9-57ee-84c3-cb4cb615ea6c','"You see," he murmured in Alexander''s ear, as the curtain fell on the first act, "one almost never sees a part like that done without smartness or mawkishness.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('d89ba964-cccd-54c5-9547-6448b91a29e3','quick','libritts:dev-clean:1462_170138_000020_000000','Clip 395 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/13f0ae61a182ec312ad0d1f93eb108abf7aaf370e9b79b6465eac62e53549e9a.wav','13f0ae61a182ec312ad0d1f93eb108abf7aaf370e9b79b6465eac62e53549e9a',429646,8950,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('d89ba964-cccd-54c5-9547-6448b91a29e3','He bowed as the warning bell rang, and Mainhall whispered: "You know Lord Westmere, of course,--the stooped man with the long gray mustache, talking to Lady Dowle.') on conflict (clip_id) do nothing;
insert into public.dictation_clips (id,bank,source_id,title,source_url,source_dataset,license_url,attribution,audio_object_key,audio_sha256,audio_bytes,duration_ms,status,qa_note) values ('03ddb266-00b5-5746-b2b3-492961879986','quick','libritts:dev-clean:1462_170138_000023_000001','Clip 396 · voice 1462','https://www.openslr.org/60/','LibriTTS dev-clean','https://creativecommons.org/licenses/by/4.0/','LibriTTS · speaker 1462 · CC BY 4.0','dictation/clips/quick/45b4c0dcafdced0f7da34daceb2d4b531a0c6fa8757969aff98f5dedfdd46c54.wav','45b4c0dcafdced0f7da34daceb2d4b531a0c6fa8757969aff98f5dedfdd46c54',86924,1810,'preview','Source-paired clip; listening QA pending') on conflict (source_id) do nothing;
insert into public.dictation_clip_answers(clip_id,reference_text) values ('03ddb266-00b5-5746-b2b3-492961879986','But I never thought she''d do anything.') on conflict (clip_id) do nothing;
