insert into public.dictation_clip_answers(clip_id,reference_text) values ('cc44c645-9c52-51c0-8da1-5c8d8d598fc7','This man was clad in a brown camel hair robe and sandals, and a green turban was on his head. His expression was tranquil, his gaze impersonal.') on conflict (clip_id) do nothing;
